package tv.plus.pro.home;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{
LinearLayout root;void page(String name){LinearLayout base=new LinearLayout(this);base.setOrientation(1);base.setPadding(24,18,24,18);base.setBackgroundColor(0xff101025);TextView h=new TextView(this);h.setText("▶ TV+  "+name+"  15.0");h.setTextColor(-1);h.setTextSize(30);base.addView(h);ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);s.addView(root);base.addView(s);setContentView(base);}
void item(String name,Runnable click){TextView t=new TextView(this);t.setText(name);t.setTextSize(23);t.setTextColor(-1);t.setPadding(22,20,22,20);t.setFocusable(true);t.setBackgroundColor(0xff302450);t.setOnFocusChangeListener((v,f)->t.setBackgroundColor(f?0xff9857ff:0xff302450));t.setOnClickListener(v->click.run());root.addView(t);}
void launch(String pkg){try{Intent i=getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(i==null)i=getPackageManager().getLaunchIntentForPackage(pkg);if(i==null){new AlertDialog.Builder(this).setTitle("Uygulama bulunamadı").setMessage(pkg+" kurulu değil veya Android TV tarafından görünmüyor.").setPositiveButton("Tamam",null).show();return;}startActivity(i);}catch(Exception e){new AlertDialog.Builder(this).setTitle("Uygulama açılamadı").setMessage(e.getClass().getSimpleName()+": "+e.getMessage()).setPositiveButton("Tamam",null).show();}}
void system(String action){try{startActivity(new Intent(action));}catch(Exception e){startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}}
@Override public void onCreate(Bundle b){super.onCreate(b);show();}
void show(){page("Ana Ekran");item("Uygulamalar",()->{page("Uygulamalar");Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);android.content.pm.PackageManager pm=getPackageManager();for(android.content.pm.ResolveInfo r:pm.queryIntentActivities(q,0)){item(r.loadLabel(pm).toString(),()->{Intent i=new Intent();i.setClassName(r.activityInfo.packageName,r.activityInfo.name);startActivity(i);});}});item("TV+ Ayarlar",()->launch("tv.plus.pro.settings"));item("TV+ Dosyalar",()->launch("tv.plus.pro.folders"));item("TV+ Galeri",()->launch("tv.plus.pro.gallery"));item("TV+ Ses",()->launch("tv.plus.pro.volume"));}


}